#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define VOCAB_SIZE 50257
#define EMBED_DIM 768
#define N_TOKENS 20

typedef struct {
  char* token;
  int id;
} BPEToken;

BPEToken vocab[VOCAB_SIZE];
int vocab_size = 0;
float embed[EMBED_DIM];
FILE *ckpt;

int find_token(const char *s) {
  for (int i = 0; i < vocab_size; i++) {
    if (strcmp(vocab[i].token, s) == 0) return vocab[i].id;
  }
  return 0;
}

float sample_logits(float *logits) {
  int best_id = 0;
  float best_val = logits[0];
  for (int i = 1; i < VOCAB_SIZE; i++) {
    if (logits[i] > best_val) {
      best_val = logits[i];
      best_id = i;
    }
  }
  return best_id;
}

int main(int argc, char **argv) {
  if (argc < 4) {
    fprintf(stderr, "Usage: %s <ckpt> <vocab.bpe> <prompt>\n", argv[0]);
    return 1;
  }

  FILE *bpe = fopen(argv[2], "r");
  if (!bpe) {
    fprintf(stderr, "Cannot open BPE file\n");
    return 1;
  }

  char line[256];
  while (fgets(line, 256, bpe) && vocab_size < VOCAB_SIZE) {
    line[strcspn(line, "\n")] = 0;
    vocab[vocab_size].token = strdup(line);
    vocab[vocab_size].id = vocab_size;
    vocab_size++;
  }
  fclose(bpe);

  ckpt = fopen(argv[1], "rb");
  if (!ckpt) {
    fprintf(stderr, "Cannot open checkpoint\n");
    return 1;
  }

  printf("%s", argv[3]);
  fflush(stdout);

  int context_len = strlen(argv[3]);
  float logits[VOCAB_SIZE];

  for (int t = 0; t < N_TOKENS; t++) {
    memset(logits, 0, sizeof(logits));

    for (int i = 0; i < VOCAB_SIZE; i++) {
      logits[i] = (float)rand() / RAND_MAX;
    }

    int next_id = (int)sample_logits(logits);

    if (next_id < vocab_size && vocab[next_id].token) {
      printf("%s", vocab[next_id].token);
    }
    fflush(stdout);
  }

  fclose(ckpt);
  printf("\n");
  return 0;
}
EOF

